/// <summary>
/// Extension of form DocuView
/// </summary>
[ExtensionOf(formStr(DocuView))]
final class AVADocuViewFrm_Extension
{

}

Method.Source:
/// <summary>
/// Extension of method init
/// </summary>
public void init()  
{
    next init();

    this.design().controlName(formControlStr(DocuView, QuickFilterControl)).setFocus();
    //this.docuRef_ds().query().dataSourceTable(tableNum(DocuRef)).addSortField(fieldNum(DocuRef, AVASortDesc), SortOrder::Descending);
    //this.docuRef_ds().query().dataSourceTable(tableNum(DocuRef)).addSortField(fieldNum(DocuRef, CreatedDateTime), SortOrder::Ascending);
    this.docuRef_ds().query().dataSourceTable(tableNum(DocuRef)).addSortField(fieldNum(DocuRef, KCS_TCVLineNum));
}

/// <summary>
/// Extension of method close
/// </summary>
public void close()
{
    next close();

    this.avaRefreshCallerUI();
}

/// <summary>
/// Researches and refreshes caller formDataSource and UI
/// </summary>
public void avaRefreshCallerUI()
{
    FormDataSource  avaFds;
    FormRun         locFormRunCaller;

    switch(actualTableId)
    {
        case tableNum(SalesQuotationTable):
        case tableNum(SalesTable):
        case tableNum(SalesQuotationLine):
        case tableNum(SalesLine):
            avaFds = FormDataUtil::getFormDataSource(actualRecord);
            avaFds.research(true);
            break;

        default:
            break;
    }

    if (this.args())
    {
        locFormRunCaller = this.args().caller();
        if (formHasMethod(locFormRunCaller, literalStr(afterDocuRefChanges)))
        {
            locFormRunCaller.afterDocuRefChanges();
        }
    }
}
